insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id)
select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-ek-201","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The rate constant $k$ of a given reaction, at fixed temperature, does not depend on","options":["the concentrations of the reactants","the presence of a catalyst (which actually changes $k$)","temperature (which actually changes $k$)","the activation energy (which actually enters $k$)"],"answer_index":0,"explanation":"$k$ is independent of concentration. It does depend on $T$, $E_a$ and catalysis; the wording isolates the concentration independence.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-202","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Dimensions of $k$ for a zero-order reaction (rate in mol L$^{-1}$ s$^{-1}$) are","options":["mol L$^{-1}$ s$^{-1}$","s$^{-1}$","L mol$^{-1}$ s$^{-1}$","L$^2$ mol$^{-2}$ s$^{-1}$"],"answer_index":0,"explanation":"Rate $= k$ when the order is zero, so $k$ carries the same units as the rate itself.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-203","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A second-order rate constant (concentration in mol L$^{-1}$, time in s) has the unit","options":["L mol$^{-1}$ s$^{-1}$","s$^{-1}$","mol L$^{-1}$ s$^{-1}$","L$^2$ mol$^{-2}$ s$^{-1}$"],"answer_index":0,"explanation":"Rate $= k[\\mathrm{A}]^2$ (or $k[\\mathrm{A}][\\mathrm{B}]$) forces $k$ to have units (concentration)$^{-1}$ (time)$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-204","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Average rate over a finite interval is computed as","options":["change in concentration divided by the elapsed time","the slope of the tangent at one instant only","the equilibrium constant divided by time","the activation energy divided by $RT$"],"answer_index":0,"explanation":"Average rate $= \\Delta[\\mathrm{ ]}/\\Delta t$. Instantaneous rate is the derivative (tangent slope).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-205","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For $2\\mathrm{N_2O_5} \\to 4\\mathrm{NO_2} + \\mathrm{O_2}$, the rate of appearance of NO$_2$ compared with the rate of disappearance of N$_2$O$_5$ is","options":["twice as large","the same","half as large","four times smaller"],"answer_index":0,"explanation":"Rate of reaction $= -\\tfrac12 \\mathrm{d}[\\mathrm{N_2O_5}]/\\mathrm{d}t = +\\tfrac14 \\mathrm{d}[\\mathrm{NO_2}]/\\mathrm{d}t$, so $-\\mathrm{d}[\\mathrm{N_2O_5}]/\\mathrm{d}t = \\tfrac12 \\mathrm{d}[\\mathrm{NO_2}]/\\mathrm{d}t$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-206","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For an elementary bimolecular collision A + B → products, the rate law is expected to be","options":["rate $= k[\\mathrm{A}][\\mathrm{B}]$","rate $= k$ only","rate $= k[\\mathrm{A}]^2[\\mathrm{B}]^2$","rate $= k / [\\mathrm{A}][\\mathrm{B}]$"],"answer_index":0,"explanation":"In an elementary step the molecularity and the order coincide, so each reactant appears to the first power.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-207","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"When a multi-step mechanism has one distinctly slow step, the observed rate law is usually that of the","options":["rate-determining (slow) step, after any pre-equilibria are substituted","fastest step alone, ignoring the slow one","overall stoichiometry in every case","reverse reaction only"],"answer_index":0,"explanation":"The bottleneck step limits the flux. Intermediates in that step are rewritten using faster equilibria if needed.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-208","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Raising the temperature of a typical thermally activated reaction increases $k$ because","options":["a larger fraction of collisions then exceeds the activation barrier","concentrations in the rate law are redefined","the stoichiometric coefficients change","the Faraday constant grows with $T$"],"answer_index":0,"explanation":"Arrhenius behaviour: $k = A e^{-E_a/RT}$ grows rapidly as $T$ rises.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-209","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The rate of the reaction $a\\mathrm{A} \\to$ products is defined so that","options":["rate $= -\\tfrac1a \\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t$","rate $= -a\\,\\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t$","rate $= +a[\\mathrm{A}]$","rate $= [\\mathrm{A}]^a$ with no $k$"],"answer_index":0,"explanation":"Dividing by the stoichiometric coefficient makes the rate the same whichever species is monitored.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-210","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If rate $= k[\\mathrm{A}]^2$ and [A] is doubled at constant $T$, the instantaneous rate becomes","options":["four times the original rate","twice the original rate","unchanged","half the original rate"],"answer_index":0,"explanation":"Second order in A: $(2)^2 = 4$, so the rate quadruples.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-211","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A reaction has rate $= 2.0 \\times 10^{-4}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$ when [A] = 0.10 M and is first order in A only. $k$ equals","options":["$2.0 \\times 10^{-3}\\ \\mathrm{s^{-1}}$","$2.0 \\times 10^{-5}\\ \\mathrm{s^{-1}}$","$2.0 \\times 10^{-4}\\ \\mathrm{L\\ mol^{-1}\\ s^{-1}}$","$0.10\\ \\mathrm{s^{-1}}$"],"answer_index":0,"explanation":"$k = \\mathrm{rate}/[\\mathrm{A}] = 2.0 \\times 10^{-4}/0.10 = 2.0 \\times 10^{-3}\\ \\mathrm{s^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-212","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For rate $= k[\\mathrm{A}][\\mathrm{B}]$ the unit of $k$ (conc. in mol L$^{-1}$) is","options":["L mol$^{-1}$ s$^{-1}$","s$^{-1}$","mol L$^{-1}$ s$^{-1}$","L$^2$ mol$^{-2}$ s$^{-1}$"],"answer_index":0,"explanation":"Two concentration factors sit with $k$, so $k$ is second-order: L mol$^{-1}$ s$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-213","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"In $2\\mathrm{A} + \\mathrm{B} \\to \\mathrm{C}$, if A disappears at $6.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$, C appears at","options":["$3.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$6.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$1.2 \\times 10^{-2}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$1.5 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$"],"answer_index":0,"explanation":"Rate $= -\\tfrac12 \\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t = +\\mathrm{d}[\\mathrm{C}]/\\mathrm{d}t$, so d[C]/dt is half of 6.0 × 10$^{-3}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-214","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Holding [B] fixed, [A] is doubled and the initial rate becomes four times larger. The order with respect to A is","options":["2","1","0","4"],"answer_index":0,"explanation":"rate ∝ [A]$^x$ and $4 = 2^x$ implies $x = 2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-215","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Two runs at the same [B]: [A] = 0.10 M gives rate $1.2 \\times 10^{-4}$; [A] = 0.20 M gives rate $4.8 \\times 10^{-4}$. Order in A and the factor by which rate changes if both [A] and [B] are doubled (order in B is 1) are","options":["2 and a factor of 8","1 and a factor of 4","2 and a factor of 4","0 and a factor of 2"],"answer_index":0,"explanation":"Rate ×4 when [A] ×2 ⇒ order 2 in A. Overall rate $= k[\\mathrm{A}]^2[\\mathrm{B}]$, so doubling both species multiplies the rate by $4 \\times 2 = 8$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-216","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Rate $= k[\\mathrm{NO}]^2[\\mathrm{O_2}]$ with $k = 1.0 \\times 10^3\\ \\mathrm{L^2\\ mol^{-2}\\ s^{-1}}$. If [NO] = 0.020 M and [O$_2$] = 0.010 M, the rate is","options":["$4.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$4.0 \\times 10^{-6}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$2.0 \\times 10^{-4}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$1.0 \\times 10^{-2}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$"],"answer_index":0,"explanation":"Rate $= 1.0 \\times 10^3 \\times (0.020)^2 \\times 0.010 = 1.0 \\times 10^3 \\times 4.0 \\times 10^{-6} = 4.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"rate-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-217","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The order of a reaction may be zero or fractional, whereas molecularity is","options":["a positive integer (1, 2 or occasionally 3) for an elementary step","always equal to zero","allowed to be negative for unimolecular decays","undefined for every elementary reaction"],"answer_index":0,"explanation":"Order is experimental and can be 0, ½, 1, 2, …. Molecularity counts the molecules in one elementary act and is a small integer.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-218","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Molecularity of an elementary step is the","options":["number of species that collide (or decompose) in that single step","sum of the stoichiometric coefficients of the overall equation always","same as the activation energy in kJ","number of products formed"],"answer_index":0,"explanation":"Unimolecular = one species rearranges; bimolecular = two species collide, and so on.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-219","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Overall order is obtained from a rate law rate $= k[\\mathrm{A}]^x[\\mathrm{B}]^y$ as","options":["$x + y$","$x - y$","$x \\times y$","$x / y$"],"answer_index":0,"explanation":"Overall order is the sum of the concentration exponents in the experimental rate law.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-220","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A pseudo-first-order reaction is typically a bimolecular process run with","options":["one reactant in large excess, so that its concentration stays nearly constant","both reactants at identical micromolar levels","no solvent present","a catalyst that raises the molecularity to four"],"answer_index":0,"explanation":"Ester hydrolysis in water is the classic case: [H$_2$O] is huge and is absorbed into an effective first-order $k$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-221","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Molecularity is a meaningful idea only for","options":["an elementary step","every complex multi-step reaction as a whole","equilibrium constants","conductivity experiments"],"answer_index":0,"explanation":"A complex reaction is a sequence of elementary steps; it has an order but not a single molecularity.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-222","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Decomposition of a single gaseous molecule in one elementary act is described as","options":["unimolecular","bimolecular","zero-order by definition","termolecular only"],"answer_index":0,"explanation":"One reactant species appears in the elementary step, so the molecularity is one.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-223","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A bimolecular elementary reaction involves","options":["a collision between two species (like or unlike)","the simultaneous meeting of four molecules","no collision at all","only a change of solvent polarity"],"answer_index":0,"explanation":"Two particles must encounter each other; the step is first order in each (or second order in one if they are identical).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-224","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Ammonia decomposition on a tungsten surface at high pressure is a familiar textbook example of a","options":["zero-order reaction","third-order gas reaction","unimolecular reaction in the gas phase only","reaction with no rate constant"],"answer_index":0,"explanation":"The surface is saturated, so the rate becomes independent of the NH$_3$ pressure: order zero.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-225","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The experimental law rate $= k[\\mathrm{H_2}][\\mathrm{Br_2}]^{1/2}$ has overall order","options":["1.5","2","0.5","1"],"answer_index":0,"explanation":"Exponents add: $1 + 1/2 = 3/2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
